t.script:
                $(document).ready(function() {
                    // Load FullCalendar
                    if (typeof FullCalendar !== 'undefined') {
                        var calendarEl = document.getElementById('calendar-container');
                        var calendar = new FullCalendar.Calendar(calendarEl, {
                            initialView: 'dayGridMonth',
                            headerToolbar: {
                                left: 'prev,next today',
                                center: 'title',
                                right: 'dayGridMonth,timeGridWeek,timeGridDay'
                            },
                            events: function(info, successCallback, failureCallback) {
                                // Fetch calendar events from the API
                                $.ajax({
                                    url: '/farm/api/order/' + $('#order_id').data('order-id') + '/calendar',
                                    method: 'POST',
                                    success: function(response) {
                                        if (response.error) {
                                            console.error('Error fetching calendar data:', response.error);
                                            successCallback([]);
                                        } else {
                                            successCallback(response.events || []);
                                        }
                                    },
                                    error: function(xhr, status, error) {
                                        console.error('Error:', error);
                                        successCallback([]);
                                    }
                                });
                            },
                            eventClick: function(info) {
                                // Show event details when clicked
                                var event = info.event;
                                var bodyContent = `

Operation: ${event.title}

Task: ${event.extendedProps.task_name}

Type: ${event.extendedProps.intervention_type}

Status: ${event.extendedProps.state}
                                `;

                                alert(bodyContent);
                            },
                            eventTimeFormat: {
                                hour: '2-digit',
                                minute: '2-digit',
                                hour12: false
                            }
                        });

                        calendar.render();
                    } else {
                        console.error('FullCalendar library not available');
                    }
                });
